"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2107],{82037:e=>{e.exports=JSON.parse('{"functions":[{"name":"reserveServer","desc":"Reserves a private server on the level place. Returns its access code, or\\nnil when the place isn\'t configured or the reserve call fails.","params":[],"returns":[{"desc":"","lua_type":"string?\\n"}],"function_type":"static","source":{"line":61,"path":"src/Server/Util/LevelTeleport.luau"}},{"name":"teleportToReserved","desc":"Sends `params.players` to an already-reserved server, retrying up to\\nQueueConfig.teleportRetries times and re-filtering disconnects on every\\nattempt.","params":[{"name":"accessCode","desc":"","lua_type":"string"},{"name":"params","desc":"","lua_type":"TeleportParams\\n"}],"returns":[{"desc":"","lua_type":"TeleportResult\\n"}],"function_type":"static","source":{"line":84,"path":"src/Server/Util/LevelTeleport.luau"}},{"name":"reserveAndTeleport","desc":"Reserve a fresh level server and send the party to it.","params":[{"name":"params","desc":"","lua_type":"TeleportParams"}],"returns":[{"desc":"","lua_type":"TeleportResult\\n"}],"function_type":"static","source":{"line":152,"path":"src/Server/Util/LevelTeleport.luau"}}],"properties":[],"types":[],"name":"LevelTeleport","desc":"The reserve-server + TeleportData + TeleportAsync core shared by every\\npath that sends a party into a fresh level server: the lobby queue\\n(QueueService) and the game-over REPLAY button (RVHealthService).\\n\\nThe TeleportData written here is the contract the level server reads on\\nboot \u2014 `mode` (RunMode.initServer), `partySize`\\n(DayCycleService.getExpectedPartySize) and `initiatorUserId` (SkillTree /\\nsession upgrades). One writer so the two entry points can never drift.\\n\\n`reserveServer` is split out so a caller that knows it will teleport\\nshortly (the replay window) can pay the reserve latency up front and\\nhand the code to `teleportToReserved` later. Callers that teleport\\nimmediately use `reserveAndTeleport`.\\n\\nEvery function here yields. Retry count / delay come from QueueConfig so\\nboth entry points behave identically.","source":{"line":24,"path":"src/Server/Util/LevelTeleport.luau"}}')}}]);